 static void Tick(){string q="docs/verification/v08/verify-request.txt";if(EditorApplication.isCompiling||!File.Exists(q))return;string cmd;try{cmd=File.ReadAllText(q).Trim();}catch(IOException){return;}if(cmd=="")return;try{File.WriteAllText(q,"");}catch(IOException){return;}if(cmd=="portrait"){Portrait();return;}if(!EditorApplication.isPlaying)return;var trade=UnityEngine.Object.FindObjectOfType<MerchantTrade>();if(trade==null)return;var p=trade.gameObject.GetComponent<MerchantProbe>();if(p==null)p=trade.gameObject.AddComponent<MerchantProbe>();p.Run(cmd);}
 static void Portrait(){var npc=UnityEngine.Object.FindObjectOfType<SnailIdle>();var go=new GameObject("Temporary merchant photo");var cam=go.AddComponent<Camera>();cam.transform.position=npc.transform.position+new Vector3(6.4f,2.8f,.25f);cam.transform.LookAt(npc.transform.position+Vector3.up*1.35f);cam.fieldOfView=36;var rt=new RenderTexture(1200,1000,24);var old=RenderTexture.active;try{cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1200,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1200,1000),0,0);tex.Apply();File.WriteAllBytes("docs/verification/v08/merchant-close.png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{RenderTexture.active=old;cam.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
}
