 var box=GameObject.CreatePrimitive(PrimitiveType.Cube);ownedObjects.Add(box);box.name="Diagnostic environment";box.transform.position=new Vector3(0,8,0);Physics.SyncTransforms();confirmBefore=feedback.TargetConfirmations;hitBefore=OrbProjectile.HitCount;shotGo=new GameObject("Diagnostic real environment projectile");ownedObjects.Add(shotGo);shotGo.transform.position=new Vector3(0,8,-2);shotGo.AddComponent<OrbProjectile>().Launch(trade.shooter.config,new OrbShotContext(shotGo.transform.position,Vector3.forward,0,trade.shooter.gameObject));yield return new WaitForSeconds(.20f);Check(OrbProjectile.HitCount==hitBefore+1&&feedback.TargetConfirmations==confirmBefore,"real environment hit no target marker");Destroy(box);
 var audio=FeedbackAudio.Instance;Check(FindObjectsOfType<AudioListener>().Count(x=>x.enabled)==1,"one enabled listener");Check(audio.clips.All(c=>c!=null&&c.loadState==AudioDataLoadState.Loaded),"all six audio assets loaded");Check(audio.GetComponentsInChildren<AudioSource>().Length==8,"audio bounded8 voices");yield return AudioCheck();Check(lastAudioPeak>.00001f,"all voices and listener output samples nonzero");
