 float lastAudioPeak;IEnumerator AudioCheck(){var a=FeedbackAudio.Instance;float sourcePeak=0,listenerPeak=0;var buffer=new float[1024];double dspStart=AudioSettings.dspTime;a.PlayCue(Cue.Purchase);for(int frame=0;frame<15;frame++){yield return new WaitForSecondsRealtime(.01f);foreach(var v in a.GetComponentsInChildren<AudioSource>()){v.GetOutputData(buffer,0);foreach(float value in buffer)sourcePeak=Mathf.Max(sourcePeak,Mathf.Abs(value));}AudioListener.GetOutputData(buffer,0);foreach(float value in buffer)listenerPeak=Mathf.Max(listenerPeak,Mathf.Abs(value));}lastAudioPeak=listenerPeak;File.WriteAllText("docs/verification/v08/audio.json",JsonUtility.ToJson(new AudioReport{sourcePeak=sourcePeak,listenerPeak=listenerPeak,dspDelta=(float)(AudioSettings.dspTime-dspStart),listenerVolume=AudioListener.volume,listenerPause=AudioListener.pause,editorMute=EditorUtility.audioMasterMute,clipStates=string.Join(",",a.clips.Select(c=>c.name+":"+c.loadState))},true));}
